<script setup lang="ts">
import { MapPin, Pencil, EllipsisVertical, Plus } from "lucide-vue-next";
import { locationApi, type LocationApiItem } from "~/api/location";
import ContractorCreateModal from "./components/ContractorCreateModal.vue";
import LocationCompaniesTab from "./components/LocationCompaniesTab.vue";
import LocationContractorsTab from "./components/LocationContractorsTab.vue";
import LocationOperationalAreasTab from "./components/LocationOperationalAreasTab.vue";
import LocationDetailCard from "./components/LocationDetailCard.vue";
import { companies as mockCompanies, areas as mockAreas, permanentContractorOptions, type DangerClass, type Company, type Contractor } from "~/data/location-detail.mock";
definePageMeta({ layout: "default" });
const route = useRoute(); const locationId = computed(() => Number(route.params.locationId ?? 1)); const { setScope } = useOrganizationScope(); const location = ref<LocationApiItem | null>(null); const locationLoading = ref(true); const locationError = ref("");
const locationView = computed(() => ({ id: locationId.value, name: location.value?.name ?? "", city: location.value?.city?.name ?? "", district: location.value?.district?.name ?? "", address: location.value?.address ?? "", image: location.value?.image ? new URL(`/storage${location.value.image.startsWith("/") ? "" : "/"}${location.value.image}`, useRuntimeConfig().public.apiBaseUrl).toString() : "", status: location.value?.is_active === false ? ("passive" as const) : ("active" as const) }));
const loadLocation = async () => { locationLoading.value = true; locationError.value = ""; try { location.value = await locationApi.get("", locationId.value); } catch (error) { locationError.value = error instanceof Error ? error.message : "Lokasyon bilgileri alınamadı."; } finally { locationLoading.value = false; } };
const activeTab = ref<"companies" | "contractors" | "areas">("companies"); const locationTabs = [{ label: "Firmalar", key: "companies" }, { label: "Alt Yükleniciler", key: "contractors" }, { label: "Operasyonel Alanlar", key: "areas" }];
const showContractorModal=ref(false); const companies = ref<Company[]>(mockCompanies); const contractors = ref<Contractor[]>([]); const areas = ref(mockAreas); const operationalAreasTab = ref<InstanceType<typeof LocationOperationalAreasTab> | null>(null); const companiesTab = ref<InstanceType<typeof LocationCompaniesTab> | null>(null);
const loadContractors = async () => { try { const items = await locationApi.organizationContractors(locationId.value); contractors.value = items.filter(x => x.contractor_type === "permanent").map(x => ({ id:x.id, name:x.name, logo:x.logo_path || "", operationalArea:"", activity:"", subActivity:"", nace:"", dangerClass:"" as DangerClass, sgk:"", status:x.status === "passive" ? "passive" : "active", contractorType:"Daimi", businessEntityId:x.id })); } catch (error) { locationError.value = error instanceof Error ? error.message : "Alt yükleniciler alınamadı."; } };
const addContractor=(p:{contractor:string;area:string;activity:string;subActivity:string;nace:string;dangerClass:DangerClass;sgk:string})=>{const c=permanentContractorOptions.find(x=>x.name===p.contractor);if(!c)return;contractors.value.push({id:Date.now(),name:c.name,logo:c.logo,operationalArea:p.area,activity:p.activity,subActivity:p.subActivity,nace:p.nace,dangerClass:p.dangerClass,sgk:p.sgk,status:"active",contractorType:"Daimi"});showContractorModal.value=false;};
onMounted(async()=>{await loadLocation();if(location.value){setScope("location",{id:location.value.id,name:location.value.name,description:"Tesis",icon:undefined});await loadContractors();}});
</script>
<template><div class="font-outfit mx-auto w-full max-w-[1400px] location-detail-refinement"><LocationDetailCard :location="locationView" /><div v-if="locationError" class="mt-3 rounded-lg border border-error-200 bg-error-50 px-4 py-3 text-sm text-error-600">{{ locationError }}</div><OrganizationTabs v-model="activeTab" :tabs="locationTabs" /><div class="mb-4 flex items-center justify-end"><button v-if="activeTab==='companies'" class="inline-flex h-10 items-center gap-2 rounded-lg bg-brand-500 px-4 text-sm font-semibold text-white" @click="companiesTab?.openCreate()"><Plus :size="16" /> Firma Ekle</button><button v-else-if="activeTab==='contractors'" class="inline-flex h-10 items-center gap-2 rounded-lg bg-brand-500 px-4 py-2 text-sm font-semibold text-white" @click="showContractorModal=true"><Plus :size="16" /> Alt Yüklenici Ekle</button><button v-else class="inline-flex h-10 items-center gap-2 rounded-lg bg-brand-500 px-4 text-sm font-semibold text-white" @click="operationalAreasTab?.openCreate()"><Plus :size="16" /> Operasyonel Alan Ekle</button></div><LocationCompaniesTab v-if="activeTab==='companies'" ref="companiesTab" :companies="companies" :areas="areas" /><LocationContractorsTab v-else-if="activeTab==='contractors'" :contractors="contractors" /><LocationOperationalAreasTab v-else ref="operationalAreasTab" :location-id="locationId" /><ContractorCreateModal v-model="showContractorModal" :contractors="permanentContractorOptions" :areas="areas" @save="addContractor" /></div></template>